        // Concurrency token
        builder.Property(l => l.RowVersion)
            .IsRowVersion()
            .IsRequired();

        // Audit columns (global rule)
        builder.Property(l => l.CreatedAt)
            .HasColumnType("datetime2")
            .HasDefaultValueSql("SYSUTCDATETIME()")
