            .IsRequired();

        builder.Property(l => l.UpdatedAt)
            .HasColumnType("datetime2")
            .HasDefaultValueSql("SYSUTCDATETIME()")
            .IsRequired(false);

        // Soft‑delete shadow property (Lesson participates in soft delete)
        builder.Property<bool>("IsDeleted")
            .HasDefaultValue(false);
        builder.HasQueryFilter(l => EF.Property<bool>(l, "IsDeleted") == false);

        // Indexes
        builder.HasIndex(l => new { l.CourseId, l.Order })
            .IsUnique()
            .HasDatabaseName("IX_Lessons_CourseId_Order");

        // Relationships (FKs) – point to the existing Lessons navigation on Course
